import re
import urllib.parse
import requests
import json
def task_func(myString, API_KEY):
    url_pattern = r'https?://[^\s,;"\'\(\)]+'
    found_urls = re.findall(url_pattern, myString)

    unique_domains = set()
    for url in found_urls:
        parsed = urllib.parse.urlparse(url)
        if parsed.hostname:
            unique_domains.add(parsed.hostname)

    geolocation_map = {}
    for domain in unique_domains:
        try:
            api_endpoint = f"http://ip-api.com/json/{domain}?key={API_KEY}"
            response = requests.get(api_endpoint, timeout=10)
            if response.status_code == 200:
                geolocation_map[domain] = json.loads(response.text)
            else:
                geolocation_map[domain] = None
        except (requests.RequestException, ValueError, json.JSONDecodeError):
            geolocation_map[domain] = None

    return geolocation_map

